import React, { createContext, useContext, useState, useEffect } from 'react';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [loading, setLoading] = useState(true);

  // On app load, auto-read from localStorage
  useEffect(() => {
    const storedUser = localStorage.getItem('shopzone_user');
    const storedToken = localStorage.getItem('shopzone_token');

    if (storedUser) setUser(JSON.parse(storedUser));
    if (storedToken) setToken(storedToken);

    setLoading(false);
  }, []);

  const login = (token, userData) => {
    localStorage.setItem('shopzone_user', JSON.stringify(userData));
    localStorage.setItem('shopzone_token', token);
    setUser(userData);
    setToken(token);
  };

  const logout = () => {
    localStorage.removeItem('shopzone_user');
    localStorage.removeItem('shopzone_token');
    setUser(null);
    setToken(null);
  };

  const role = user?.role || null;
  const isAuthenticated = !!user && !!token;

  return (
    <AuthContext.Provider value={{ 
      user, 
      token, 
      role, 
      isAuthenticated, 
      login, 
      logout, 
      loading 
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
